import importlib, importlib.metadata as md, importlib.util, json, subprocess, sys
for name in ['onnxruntime','tflite_runtime','tvm','dlr','tidlruntime','cv2','numpy']:
    if importlib.util.find_spec(name) is None:
        print(json.dumps({'module':name,'installed':False}), flush=True)
        continue
    code = 'import '+name+' as m; import json; print(json.dumps(dict(module='+repr(name)+', version=getattr(m,"__version__","unreported"), path=m.__file__)))'
    if name == 'onnxruntime': code += '; print("providers:",m.get_available_providers())'
    try:
        r=subprocess.run([sys.executable,'-c',code],capture_output=True,text=True,timeout=25)
        print(r.stdout, end='', flush=True)
        if r.returncode: print('IMPORT_ERROR',name,r.stderr,flush=True)
    except subprocess.TimeoutExpired: print('IMPORT_TIMEOUT',name,flush=True)
for d in md.distributions():
    name=d.metadata.get('Name','')
    if name.lower() in ['onnxruntime-tidl','tflite-runtime','tvm','dlr','tidlruntime','numpy','opencv']:
        print('distribution:',name,d.version,str(d.locate_file('')),flush=True)
